{
        // Arrange
        var channel = new AnalogChannel(0, 65535)
        {
            PortRange = 1.0,
            CalibrationM = 1.0,
            CalibrationB = 0.0,
            InternalScaleM = 10.0
        };

        // Act
        var result = channel.GetScaledValue(32767); // Half value

        // Assert
        // Expected: ((32767 / 65535) * 1.0 * 1.0 + 0.0) * 10.0 ≈ 5.0
        Assert.Equal(5.0, result, precision: 2);
    }
